import React, { useMemo, useState } from 'react';
import { useApp } from '../../lib/AppContext';
import { formatLabel, statuses } from '../../lib/reportData';
import ReportsTable from '../../components/reports/ReportsTable';

export default function ReportsPage() {
  const { reports, notify } = useApp();
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState('All status');
  const [category, setCategory] = useState('All categories');
  const categories = [...new Set(reports.map(report => report.category))];
  const filtered = useMemo(() => reports.filter(report => (status === 'All status' || report.status === status) && (category === 'All categories' || report.category === category) && `${report.id} ${report.location} ${report.description} ${report.category}`.toLowerCase().includes(query.toLowerCase())), [reports, query, status, category]);
  return <><div className="page-heading"><div><div className="eyebrow">CASE MANAGEMENT</div><h1>Reports queue</h1><p>Review, assign and track environmental cases.</p></div><button className="primary" onClick={() => notify('Report export prepared')}>⇩ Export reports</button></div><div className="queue-summary"><div><b>{reports.length}</b><span>Total reports</span></div><div><b>{reports.filter(report => report.status === 'SUBMITTED').length}</b><span>Awaiting review</span></div><div><b>{reports.filter(report => report.status === 'IN_PROGRESS').length}</b><span>In progress</span></div><div><b>{reports.filter(report => report.status === 'RESOLVED').length}</b><span>Resolved</span></div></div><section className="panel table-panel"><div className="table-toolbar"><div className="search"><span>⌕</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search by case, location or keyword…"/></div><select value={status} onChange={event => setStatus(event.target.value)}><option>All status</option>{statuses.map(value => <option key={value} value={value}>{formatLabel(value)}</option>)}</select><select value={category} onChange={event => setCategory(event.target.value)}><option>All categories</option>{categories.map(value => <option key={value}>{value}</option>)}</select><button className="filter-button" onClick={() => { setStatus('All status'); setCategory('All categories'); setQuery(''); }}>↺ Reset</button></div><ReportsTable reports={filtered}/><div className="table-footer"><span>Showing <b>{filtered.length ? 1 : 0}–{filtered.length}</b> of <b>{filtered.length}</b> reports</span><div><button disabled>← Previous</button><button className="page-active">1</button><button disabled>Next →</button></div></div></section></>;
}
